final class PatientResourceComposerAdminPage{private string$hook='';public function __construct(private PatientEducationCatalogRepository$catalog,private PatientResourceVariantService$variants,private VariantRepository$variantRepository,private BrandingRepository$branding,private ResourceReader$resources,private StructuredContentRenderer$renderer,private CurrentOrganizationResolver$organizations,private Logger$logger){}public function register():void{$this->hook=(string)add_submenu_page('atlas',__('Patient Resources','atlas-platform'),__('Patient Resources','atlas-platform'),'atlas_manage_branding','atlas-patient-resources',[$this,'render']);}public function enqueue(string$hook):void{if($hook===$this->hook){wp_enqueue_style('atlas-preview',ATLAS_PLATFORM_URL.'assets/css/atlas-preview.css',[],ATLAS_PLATFORM_VERSION);}}public function create():void{if(!current_user_can('atlas_manage_branding')){wp_die(esc_html__('You are not allowed to compose patient resources.','atlas-platform'),'', ['response'=>403]);}check_admin_referer('atlas_create_patient_resource');$organization=$this->organizations->resolveForUser(get_current_user_id());if($organization===null){$this->redirect('context-required');}$selection=sanitize_text_field(wp_unslash((string)($_POST['resource_selection']??'')));[$resource,$version]=array_pad(explode('|',$selection,2),2,'');$allowed=false;foreach($this->catalog->publishedForContext($organization->id)as$item){if($item->resourceId===$resource&&$item->versionId===$version){$allowed=true;break;}}if(!$allowed){$this->redirect('not-found');}$custom=['clinic_phone'=>sanitize_text_field(wp_unslash((string)($_POST['clinic_phone']??''))),'clinic_address'=>sanitize_textarea_field(wp_unslash((string)($_POST['clinic_address']??''))),'approved_footer'=>sanitize_textarea_field(wp_unslash((string)($_POST['approved_footer']??'')))];try{$variant=$this->variants->save($organization->id,$version,$custom,sanitize_text_field(wp_unslash((string)($_POST['idempotency_key']??''))),get_current_user_id());if($variant===null){$this->redirect('not-found');}$url=add_query_arg(['page'=>'atlas-patient-resources','atlas_notice'=>$variant->replayed?'restored':'created','variant_id'=>$variant->id,'resource_id'=>$resource],admin_url('admin.php'));}catch(Throwable$failure){$this->logger->log('error','patient_resources.admin_variant_failed','Patient Resource composition failed.',[],'patient_resources',$failure);$url=add_query_arg(['page'=>'atlas-patient-resources','atlas_notice'=>'failed'],admin_url('admin.php'));}wp_safe_redirect($url);exit;}public function render():void{if(!current_user_can('atlas_manage_branding')){wp_die(esc_html__('You are not allowed to compose patient resources.','atlas-platform'),'', ['response'=>403]);}$organization=$this->organizations->resolveForUser(get_current_user_id());$items=$organization===null?[]:$this->catalog->publishedForContext($organization->id);$notice=sanitize_key(wp_unslash((string)($_GET['atlas_notice']??'')));$variantId=sanitize_text_field(wp_unslash((string)($_GET['variant_id']??'')));$resourceId=sanitize_text_field(wp_unslash((string)($_GET['resource_id']??'')));$variant=$organization===null||$variantId===''?null:$this->variantRepository->findForOrganization($variantId,$organization->id);$resource=$organization===null||$resourceId===''?null:$this->resources->findPublished($resourceId,$organization->id);if($variant!==null&&($resource===null||$resource->version->id!==$variant->resourceVersionId)){$variant=null;$resource=null;}$brand=$organization===null?null:($this->branding->findForOrganization($organization->id)??BrandingProfile::neutral($organization->id,$organization->name));$bodyHtml=$resource===null?'':$this->renderer->render($resource->version->body);require ATLAS_PLATFORM_DIR.'templates/patient-resources/composer.php';}private function redirect(string$notice):never{wp_safe_redirect(add_query_arg(['page'=>'atlas-patient-resources','atlas_notice'=>$notice],admin_url('admin.php')));exit;}}
